import { NextResponse } from 'next/server';
export const dynamic = 'force-dynamic';

const RIOT_API_KEY = process.env.RIOT_API_KEY || 'YOUR_RIOT_API_KEY_HERE';

async function fetchRiotPUUID(gameName: string, tagLine: string): Promise<string> {
  const url = `https://americas.api.riotgames.com/riot/account/v1/accounts/by-riot-id/${encodeURIComponent(
    gameName
  )}/${encodeURIComponent(tagLine)}`;
  const res = await fetch(url, {
    headers: { 'X-Riot-Token': RIOT_API_KEY },
    // Avoid cached account lookups
    cache: 'no-store',
  });
  if (!res.ok) throw new Error(`Failed to fetch PUUID: ${res.status} ${res.statusText}`);
  const data = (await res.json()) as { puuid: string };
  return data.puuid;
}

async function fetchMatchIds(puuid: string, startTime: number, endTime: number): Promise<string[]> {
  const url = `https://americas.api.riotgames.com/lol/match/v5/matches/by-puuid/${puuid}/ids?startTime=${startTime}&endTime=${endTime}&start=0&count=100`;
  const res = await fetch(url, {
    headers: { 'X-Riot-Token': RIOT_API_KEY },
    cache: 'no-store',
  });
  if (!res.ok) throw new Error(`Failed to fetch match IDs: ${res.status} ${res.statusText}`);
  return (await res.json()) as string[];
}

async function fetchMatchesBatch(matchIds: string[]): Promise<unknown[]> {
  const batchResults: unknown[] = [];
  for (const id of matchIds) {
    const url = `https://americas.api.riotgames.com/lol/match/v5/matches/${id}`;
    const res = await fetch(url, {
      headers: { 'X-Riot-Token': RIOT_API_KEY },
      cache: 'no-store',
    });
    if (res.ok) {
      batchResults.push(await res.json());
    }
  }
  return batchResults;
}

async function fetchTimeline(matchId: string): Promise<unknown | null> {
  const url = `https://americas.api.riotgames.com/lol/match/v5/matches/${matchId}/timeline`;
  const res = await fetch(url, {
    headers: { 'X-Riot-Token': RIOT_API_KEY },
    cache: 'no-store',
  });
  if (!res.ok) return null;
  return res.json();
}

type FilteredParticipant = {
  puuid?: string;
  championName?: string;
  item0?: number; item1?: number; item2?: number; item3?: number; item4?: number; item5?: number; item6?: number;
  itemsPurchased?: number;
  consumablesPurchased?: number;
  goldEarned?: number;
  goldSpent?: number;
};

type FilteredMatch = {
  matchId: string;
  gameMode?: string;
  participants: FilteredParticipant[];
  timeline?: {
    itemPurchases: Array<{ timestamp: number; itemId: number; participantId?: number; puuid?: string }>;
    currentGoldFrames: Array<{ timestamp: number; byPuuid: Record<string, number> }>;
  };
};

function filterMatchData(match: unknown): FilteredMatch | null {
  const obj = (match ?? {}) as Record<string, unknown>;
  const metadata = (obj.metadata ?? {}) as Record<string, unknown>;
  const info = (obj.info ?? {}) as Record<string, unknown>;
  const matchId = typeof metadata.matchId === 'string' ? metadata.matchId : '';
  if (!matchId) return null;
  const gameMode = typeof info.gameMode === 'string' ? (info.gameMode as string) : undefined;
  const participantsUnknown = (info.participants ?? []) as unknown[];
  const participants: FilteredParticipant[] = participantsUnknown.map((p) => {
    const pr = (p ?? {}) as Record<string, unknown>;
    const fp: FilteredParticipant = {
      puuid: typeof pr.puuid === 'string' ? (pr.puuid as string) : undefined,
      championName: typeof pr.championName === 'string' ? (pr.championName as string) : undefined,
      item0: typeof pr.item0 === 'number' ? (pr.item0 as number) : undefined,
      item1: typeof pr.item1 === 'number' ? (pr.item1 as number) : undefined,
      item2: typeof pr.item2 === 'number' ? (pr.item2 as number) : undefined,
      item3: typeof pr.item3 === 'number' ? (pr.item3 as number) : undefined,
      item4: typeof pr.item4 === 'number' ? (pr.item4 as number) : undefined,
      item5: typeof pr.item5 === 'number' ? (pr.item5 as number) : undefined,
      item6: typeof pr.item6 === 'number' ? (pr.item6 as number) : undefined,
      itemsPurchased: typeof pr.itemsPurchased === 'number' ? (pr.itemsPurchased as number) : undefined,
      consumablesPurchased: typeof pr.consumablesPurchased === 'number' ? (pr.consumablesPurchased as number) : undefined,
      goldEarned: typeof pr.goldEarned === 'number' ? (pr.goldEarned as number) : undefined,
      goldSpent: typeof pr.goldSpent === 'number' ? (pr.goldSpent as number) : undefined,
    };
    return fp;
  });
  return { matchId, gameMode, participants };
}

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const gameName = searchParams.get('gameName');
    const tagLine = searchParams.get('tagLine');
    const includeTimeline = searchParams.get('includeTimeline') === 'true';

    if (!gameName || !tagLine) {
      return NextResponse.json({ error: 'Missing gameName or tagLine' }, { status: 400 });
    }

    // 1. Get PUUID
    const puuid = await fetchRiotPUUID(gameName, tagLine);

    // 2. Calculate start and end timestamps for last year
    const now = Math.floor(Date.now() / 1000);
    const oneYearAgo = now - 365 * 24 * 60 * 60;

    // 3. Fetch all match IDs for last year
    const matchIds = await fetchMatchIds(puuid, oneYearAgo, now);

    // 4. Fetch match info in batches of 10
    let allMatches: unknown[] = [];
    for (let i = 0; i < matchIds.length; i += 10) {
      const batch = matchIds.slice(i, i + 10);
      // eslint-disable-next-line no-await-in-loop
      const matches = await fetchMatchesBatch(batch);
      allMatches = allMatches.concat(matches);
    }

    // 5. Filter down to required fields per BuildAgent spec
    const filteredBase: FilteredMatch[] = [];
    for (const m of allMatches) {
      const fm = filterMatchData(m);
      if (fm) filteredBase.push(fm);
    }

    // 6. Optionally augment with timeline data (item purchase events and currentGold)
    if (includeTimeline) {
      for (let i = 0; i < filteredBase.length; i += 1) {
        const fm = filteredBase[i];
        // eslint-disable-next-line no-await-in-loop
        const timeline = await fetchTimeline(fm.matchId);
        if (timeline && typeof timeline === 'object') {
          const t = timeline as Record<string, unknown>;
          const info = (t.info ?? {}) as Record<string, unknown>;
          const frames = Array.isArray(info.frames) ? (info.frames as unknown[]) : [];

          const itemPurchases: Array<{ timestamp: number; itemId: number; participantId?: number; puuid?: string }> = [];
          const currentGoldFrames: Array<{ timestamp: number; byPuuid: Record<string, number> }> = [];

          for (const f of frames) {
            const fr = (f ?? {}) as Record<string, unknown>;
            const ts = typeof fr.timestamp === 'number' ? (fr.timestamp as number) : undefined;
            // events
            const events = Array.isArray(fr.events) ? (fr.events as unknown[]) : [];
            for (const e of events) {
              const ev = (e ?? {}) as Record<string, unknown>;
              if (ev.type === 'ITEM_PURCHASED' && typeof ev.itemId === 'number') {
                itemPurchases.push({
                  timestamp: typeof ev.timestamp === 'number' ? (ev.timestamp as number) : (ts ?? 0),
                  itemId: ev.itemId as number,
                  participantId: typeof ev.participantId === 'number' ? (ev.participantId as number) : undefined,
                  puuid: typeof ev.puuid === 'string' ? (ev.puuid as string) : undefined,
                });
              }
            }
            // currentGold per frame by puuid
            const pf = (fr.participantFrames ?? {}) as Record<string, unknown>;
            const byPuuid: Record<string, number> = {};
            for (const key of Object.keys(pf)) {
              const entry = (pf[key] ?? {}) as Record<string, unknown>;
              const puuid = typeof entry.puuid === 'string' ? (entry.puuid as string) : undefined;
              const cg = typeof entry.currentGold === 'number' ? (entry.currentGold as number) : undefined;
              if (puuid && typeof cg === 'number') {
                byPuuid[puuid] = cg;
              }
            }
            if (ts !== undefined) {
              currentGoldFrames.push({ timestamp: ts, byPuuid });
            }
          }
          fm.timeline = { itemPurchases, currentGoldFrames };
        }
      }
    }

    // 7. Return both original matches and filtered view for compatibility
    return NextResponse.json({ matches: allMatches, filtered: filteredBase }, { status: 200 });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
